const rows = items.map(i => i.json);

const newExpense = $('Supabase - Insert Expense').first().json;

let total = 0;
const byCategory = {};

for (const row of rows) {
  const amt = Number(row.amount) || 0;
  total += amt;
  const cat = row.category || 'Other';
  byCategory[cat] = (byCategory[cat] || 0) + amt;
}

const categoryRows = Object.entries(byCategory)
  .sort((a, b) => b[1] - a[1])
  .map(([cat, amt]) => `<tr><td style="padding:6px 12px;border-bottom:1px solid #eee;">${cat}</td><td style="padding:6px 12px;border-bottom:1px solid #eee;text-align:right;">${amt.toFixed(2)}</td></tr>`)
  .join('');

const currency = newExpense.currency || 'PKR';
const newAmount = Number(newExpense.amount) || 0;

const html = `
<div style="font-family:Arial,sans-serif;max-width:600px;margin:auto;">
  <h2 style="color:#2c3e50;">New Expense Recorded</h2>
  <table style="width:100%;border-collapse:collapse;margin-bottom:24px;">
    <tr><td style="padding:6px 12px;"><b>Amount</b></td><td style="padding:6px 12px;">${currency} ${newAmount.toFixed(2)}</td></tr>
    <tr><td style="padding:6px 12px;"><b>Category</b></td><td style="padding:6px 12px;">${newExpense.category}</td></tr>
    <tr><td style="padding:6px 12px;"><b>Description</b></td><td style="padding:6px 12px;">${newExpense.description}</td></tr>
    <tr><td style="padding:6px 12px;"><b>Merchant</b></td><td style="padding:6px 12px;">${newExpense.merchant}</td></tr>
    <tr><td style="padding:6px 12px;"><b>Payment Method</b></td><td style="padding:6px 12px;">${newExpense.payment_method}</td></tr>
    <tr><td style="padding:6px 12px;"><b>Date</b></td><td style="padding:6px 12px;">${newExpense.expense_date}</td></tr>
  </table>

  <h2 style="color:#2c3e50;">Expense Summary (All Time)</h2>
  <p><b>Total Spent:</b> ${currency} ${total.toFixed(2)} &nbsp;|&nbsp; <b>Total Entries:</b> ${rows.length}</p>
  <table style="width:100%;border-collapse:collapse;">
    <tr style="background:#f5f5f5;"><th style="padding:6px 12px;text-align:left;">Category</th><th style="padding:6px 12px;text-align:right;">Total</th></tr>
    ${categoryRows}
  </table>
  <p style="color:#888;font-size:12px;margin-top:20px;">Automated report from your Expense Tracker workflow.</p>
</div>
`;

return [{
  json: {
    subject: `Expense Report - New: ${currency} ${newAmount.toFixed(2)} on ${newExpense.category}`,
    html
  }
}];
